export class InventoryGateway {                      // typed facade
  private pending = new Map<string, (v: Stock) => void>();

  async checkStock(sku: string): Promise<Stock> {    // method call, not messaging
    const corrId = randomUUID();
    const reply = new Promise<Stock>(res => this.pending.set(corrId, res));
    this.channel.publish('inventory', 'check', Buffer.from(sku),
                         { replyTo: this.replyQueue, correlationId: corrId });
    return reply;
  }
}
